source='''from collections import Counter, defaultdict, deque

def components(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    out = []
    for r in range(h):
        for c in range(w):
            if (r, c) in seen:
                continue
            color = grid[r][c]
            seen.add((r, c))
            q = [(r, c)]
            for x, y in q:
                for a, b in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0 <= a < h and 0 <= b < w and (a,b) not in seen and grid[a][b] == color:
                        seen.add((a,b)); q.append((a,b))
            out.append((color, q))
    return out

def is_l(cells):
    rs = [r for r,c in cells]; cs = [c for r,c in cells]
    r0,r1,c0,c1 = min(rs),max(rs),min(cs),max(cs)
    if r0 == r1 or c0 == c1:
        return False
    s = set(cells)
    corners = [((r0,c0),(r0,c1),(r1,c0)), ((r0,c1),(r0,c0),(r1,c1)),
               ((r1,c0),(r0,c0),(r1,c1)), ((r1,c1),(r0,c1),(r1,c0))]
    for corner, end1, end2 in corners:
        a,b=corner; x,y=end1; u,v=end2
        leg1 = {(a+k*(1 if x>a else -1), b) for k in range(abs(x-a)+1)} if b==y else {(a,b+k*(1 if y>b else -1)) for k in range(abs(y-b)+1)}
        leg2 = {(a+k*(1 if u>a else -1), b) for k in range(abs(u-a)+1)} if b==v else {(a,b+k*(1 if v>b else -1)) for k in range(abs(v-b)+1)}
        if s == leg1 | leg2:
            return True
    return False

def shape_key(cells):
    pts = list(cells)
    variants=[]
    for reflect in (False, True):
        for rot in range(4):
            trans=[]
            for r,c in pts:
                x,y=r,(-c if reflect else c)
                for _ in range(rot): x,y=y,-x
                trans.append((x,y))
            mr=min(x for x,y in trans); mc=min(y for x,y in trans)
            variants.append(tuple(sorted((x-mr,y-mc) for x,y in trans)))
    return min(variants)

def transform(grid):
    comps = components(grid)
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    objs = [(col, cells) for col,cells in comps if col != bg]
    ls = [(col,cells) for col,cells in objs if is_l(cells)]
    if not ls:
        return [row[:] for row in grid]
    key_color, key_cells = max(ls, key=lambda z: len(z[1]))
    groups=defaultdict(list)
    for col,cells in objs:
        if set(cells) != set(key_cells):
            groups[shape_key(cells)].append((col,cells))
    repeated=[g for g in groups.values() if len(g)>1]
    if not repeated:
        return [row[:] for row in grid]
    group=max(repeated,key=lambda g: len(g[0][1]))
    # Select the uppermost copy; if tied, use the one closest to the L-shaped color cue.
    keycenter=(sum(r for r,c in key_cells)/len(key_cells),sum(c for r,c in key_cells)/len(key_cells))
    def rank(obj):
        col,cells=obj
        top=min(r for r,c in cells)
        dist=min(abs(r-a)+abs(c-b) for r,c in cells for a,b in key_cells)
        return (top, dist)
    target=min(group,key=rank)
    out=[row[:] for row in grid]
    for r,c in target[1]:
        out[r][c]=key_color
    return out
'''
